    // async function savePanLian() {
    //   await api('/website/api/panlian/account',{method:'PUT',body:JSON.stringify({account:$('panLianAccount').value,password:$('panLianPassword').value})});
    //   toast('\u76D8\u94FE\u8D26\u53F7\u5DF2\u4FDD\u5B58\u5E76\u767B\u5F55\u6210\u529F');
    //   await refresh();
